// features/lifecycle.feature: "Once a vendor is sent back, its other documents cannot be decided"
import { expect, expectStatus, test } from "../../fixtures";

test("approving a document after its vendor was sent back is refused with 409", { tag: "@LIF-03" }, async ({ factory, apiAs }) => {
  // Arrange: a vendor in review, and a reviewer who rejects its w9 (which sends the vendor back)
  const { vendor, documents, extractions } = await factory.vendorInReview({ as: "member" });
  const reviewer = await apiAs("reviewer");
  const rejected = await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
    data: { decision: "reject", note: "Please re-upload the W-9." },
  });
  await expectStatus(rejected, 200);

  // Act: the reviewer tries to approve the contract extraction of the same vendor
  const response = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert: refused with the stable error code
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_not_in_review");

  // Assert: the stored outcome is unchanged, so the contract is still awaiting a decision
  const stored = await factory.extraction(documents.contract.id, "reviewer");
  expect(stored.status).toBe("pending_review");
  expect(vendor.id).toBeTruthy();
});
